css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .pagina-ops{display: grid; grid-template-columns: repeat(4, 1fr); gap: 38px 24px; justify-items: center;}
.mz .op-col{font-family: sans-serif; font-size: 22px; font-weight: 700; text-align: right; line-height: 1.3; min-width: 85px;}
.mz .op-col .lin{display: flex; justify-content: flex-end; align-items: center; gap: 10px;}
.mz .op-col .sg{font-weight: 800; font-size: 20px;}
.mz .op-col .barra{border-top: 2px solid var(--bosque); margin-top: 4px; padding-top: 6px; min-height: 34px;}
